<?php
function report_is_as_of($key){return in_array($key,['stocks','restricted','platforms','stock_balance_detail'],true);}
function report_public_filters($f){if(report_is_as_of($f['report']??'')){unset($f['from'],$f['to']);}else unset($f['as_of']);return $f;}
function report_period_label($f){return report_is_as_of($f['report']??'')?'As Of '.$f['as_of']:$f['from'].' — '.$f['to'];}
function report_readable_filters($f){$labels=['q'=>'Search','brand'=>'Brand','main_category'=>'Main Category','subcategory'=>'Subcategory','platform'=>'Platform'];$text=[];foreach($labels as $k=>$label)if(($f[$k]??'')!=='')$text[]=$label.': '.$f[$k];if(!empty($f['product_id'])){$q=db()->prepare('SELECT master_sku,name FROM products WHERE id=?');$q->execute([$f['product_id']]);if($p=$q->fetch())$text[]='Product: '.$p['master_sku'].' — '.$p['name'];}return implode(' · ',$text)?:'All matching items';}
function report_export_rows($r){return !empty($r['totals_row'])?array_merge($r['rows'],[$r['totals_row']]):$r['rows'];}
function stock_balance_breakdown($pid,$date){if(!$pid)throw new Exception('Select a product for the stock balance breakdown.');$q=db()->prepare('SELECT * FROM products WHERE id=?');$q->execute([$pid]);$p=$q->fetch();if(!$p)throw new Exception('Product not found.');$r=inventory_report_build(['report'=>'stock_balance_detail','product_id'=>$pid,'as_of'=>$date]);echo '<div class="page-head"><div><h1>Stock Balance Breakdown</h1><p>'.e($p['master_sku'].' — '.$p['name']).'</p></div><a class="btn ghost" href="?page=reports&amp;report=stocks&amp;as_of='.e($date).'">Back to Stock Balance</a></div>';report_render_result($r,'stock_balance_detail');}
